-- PostgreSQL schema generated from the supplied MariaDB export (18 October 2026).
-- Idempotent: does not delete existing Neon data.

CREATE TABLE IF NOT EXISTS "brokers" (
  "broker_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" INTEGER NOT NULL,
  "company_name" VARCHAR(100) DEFAULT NULL,
  "license_number" VARCHAR(50) DEFAULT NULL,
  PRIMARY KEY ("broker_id")
);

CREATE TABLE IF NOT EXISTS "buy_orders" (
  "order_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "investor_id" INTEGER NOT NULL,
  "company_id" INTEGER NOT NULL,
  "amount_deposited" NUMERIC(15,2) DEFAULT NULL,
  "broker_id" INTEGER DEFAULT NULL,
  "first_approver_id" INTEGER DEFAULT NULL,
  "first_approved_at" TIMESTAMP DEFAULT NULL,
  "quantity" INTEGER DEFAULT NULL,
  "price" NUMERIC(12,2) DEFAULT NULL,
  "commission" NUMERIC(12,2) DEFAULT 0.00,
  "vat" NUMERIC(12,2) DEFAULT 0.00,
  "total_amount" NUMERIC(12,2) DEFAULT 0.00,
  "proof_of_payment_path" VARCHAR(255) DEFAULT NULL,
  "status" TEXT DEFAULT 'pending' CHECK ("status" IN ('pending', 'first_approved', 'approved', 'rejected')),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expiry_date" DATE DEFAULT NULL,
  PRIMARY KEY ("order_id")
);

CREATE TABLE IF NOT EXISTS "companies" (
  "company_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "company_name" VARCHAR(150) NOT NULL,
  "ticker" VARCHAR(20) NOT NULL,
  "sector" VARCHAR(50) DEFAULT NULL,
  "current_price" NUMERIC(12,2) DEFAULT 0.00,
  "total_shares_issued" BIGINT DEFAULT NULL,
  "market_cap" NUMERIC(15,2) DEFAULT NULL,
  "listing_date" DATE DEFAULT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("company_id"),
  UNIQUE ("ticker"),
  "available_shares" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "investors" (
  "investor_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" INTEGER NOT NULL,
  "firstname" VARCHAR(50) NOT NULL,
  "surname" VARCHAR(50) NOT NULL,
  "other_names" VARCHAR(100) DEFAULT NULL,
  "date_of_birth" DATE DEFAULT NULL,
  "marital_status" VARCHAR(20) DEFAULT NULL,
  "spouse_full_name" VARCHAR(100) DEFAULT NULL,
  "gender" TEXT NOT NULL CHECK ("gender" IN ('male', 'female', 'other')),
  "phone_number" VARCHAR(20) NOT NULL,
  "national_id_number" VARCHAR(50) NOT NULL,
  "id_expiry_date" DATE DEFAULT NULL,
  "nationality" VARCHAR(50) NOT NULL DEFAULT 'Malawian',
  "foreign_local" TEXT DEFAULT 'local' CHECK ("foreign_local" IN ('local', 'foreign')),
  "residential_permit_type" VARCHAR(100) DEFAULT NULL,
  "meter_number" VARCHAR(50) NOT NULL,
  "utility_receipt_path" VARCHAR(255) DEFAULT NULL,
  "bank_statement_path" VARCHAR(255) DEFAULT NULL,
  "id_document_path" VARCHAR(255) DEFAULT NULL,
  "account_status" TEXT DEFAULT 'pending' CHECK ("account_status" IN ('pending', 'verified', 'rejected')),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "physical_address" VARCHAR(255) DEFAULT NULL,
  "postal_address" VARCHAR(255) DEFAULT NULL,
  "house_number" VARCHAR(50) DEFAULT NULL,
  "home_village" VARCHAR(100) DEFAULT NULL,
  "ta" VARCHAR(100) DEFAULT NULL,
  "district" VARCHAR(50) DEFAULT NULL,
  "directions" TEXT DEFAULT NULL,
  "next_of_kin_name" VARCHAR(100) DEFAULT NULL,
  "next_of_kin_phone" VARCHAR(20) DEFAULT NULL,
  "next_of_kin_email" VARCHAR(100) DEFAULT NULL,
  "next_of_kin_relationship" VARCHAR(50) DEFAULT NULL,
  "employment_status" TEXT DEFAULT NULL CHECK ("employment_status" IN ('employed', 'self_employed', 'not_employed')),
  "employer_name" VARCHAR(150) DEFAULT NULL,
  "designation" VARCHAR(100) DEFAULT NULL,
  "employer_address" VARCHAR(255) DEFAULT NULL,
  "years_self_employed" INTEGER DEFAULT NULL,
  "business_type" VARCHAR(150) DEFAULT NULL,
  "source_of_income" VARCHAR(150) DEFAULT NULL,
  "expected_monthly_income" TEXT DEFAULT NULL CHECK ("expected_monthly_income" IN ('below_300k', '300k_to_5m', 'above_5m')),
  "bank_name" VARCHAR(100) DEFAULT NULL,
  "bank_branch" VARCHAR(100) DEFAULT NULL,
  "bank_account_type" VARCHAR(50) DEFAULT NULL,
  "bank_account_number" VARCHAR(50) DEFAULT NULL,
  "proof_of_residence_type" TEXT DEFAULT NULL CHECK ("proof_of_residence_type" IN ('escom', 'water_board', 'mtl', 'city_ground_rates', 'mhc_invoice', 'other')),
  "account_type" TEXT DEFAULT 'equity_trading' CHECK ("account_type" IN ('equity_trading', 'money_market')),
  PRIMARY KEY ("investor_id")
);

CREATE TABLE IF NOT EXISTS "messages" (
  "message_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "sender" INTEGER NOT NULL,
  "receiver" INTEGER NOT NULL,
  "message" TEXT NOT NULL,
  "date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("message_id"),
  "is_read" INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "portfolio" (
  "portfolio_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "investor_id" INTEGER NOT NULL,
  "company_id" INTEGER NOT NULL,
  "shares_owned" INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("portfolio_id"),
  UNIQUE ("investor_id", "company_id")
);

CREATE TABLE IF NOT EXISTS "sell_orders" (
  "sell_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "investor_id" INTEGER NOT NULL,
  "company_id" INTEGER NOT NULL,
  "broker_id" INTEGER DEFAULT NULL,
  "first_approver_id" INTEGER DEFAULT NULL,
  "first_approved_at" TIMESTAMP DEFAULT NULL,
  "quantity" INTEGER NOT NULL,
  "price" NUMERIC(12,2) DEFAULT NULL,
  "commission" NUMERIC(12,2) DEFAULT NULL,
  "vat" NUMERIC(12,2) DEFAULT NULL,
  "total_amount" NUMERIC(12,2) DEFAULT NULL,
  "status" TEXT DEFAULT 'pending' CHECK ("status" IN ('pending', 'first_approved', 'approved', 'rejected')),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expiry_date" DATE DEFAULT NULL,
  PRIMARY KEY ("sell_id")
);

CREATE TABLE IF NOT EXISTS "share_prices" (
  "price_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "company_id" INTEGER NOT NULL,
  "price" NUMERIC(12,2) NOT NULL,
  "volume_traded" INTEGER DEFAULT 0,
  "date_recorded" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("price_id")
);

CREATE TABLE IF NOT EXISTS "transactions" (
  "transaction_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "investor_id" INTEGER NOT NULL,
  "company_id" INTEGER NOT NULL,
  "buy_order_id" INTEGER DEFAULT NULL,
  "sell_order_id" INTEGER DEFAULT NULL,
  "type" TEXT NOT NULL CHECK ("type" IN ('buy', 'sell')),
  "quantity" INTEGER NOT NULL,
  "price" NUMERIC(12,2) NOT NULL,
  "transaction_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "settlement_date" DATE DEFAULT NULL,
  "deal_note_number" VARCHAR(30) DEFAULT NULL,
  PRIMARY KEY ("transaction_id")
);

CREATE TABLE IF NOT EXISTS "users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "fullname" VARCHAR(100) NOT NULL,
  "email" VARCHAR(100) NOT NULL,
  "phone" VARCHAR(20) DEFAULT NULL,
  "password" VARCHAR(255) NOT NULL,
  "role" TEXT NOT NULL CHECK ("role" IN ('investor', 'broker', 'admin')),
  "status" TEXT DEFAULT 'pending' CHECK ("status" IN ('pending', 'approved', 'suspended')),
  "created_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "reset_token" VARCHAR(255) DEFAULT NULL,
  "reset_token_expiry" TIMESTAMP DEFAULT NULL,
  PRIMARY KEY ("user_id"),
  UNIQUE ("email")
);

