CREATE TABLE IF NOT EXISTS audit_log (
 log_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 user_id INTEGER REFERENCES users(user_id) ON DELETE SET NULL,
 user_name VARCHAR(150), role VARCHAR(20), action VARCHAR(100) NOT NULL,
 entity_type VARCHAR(100), entity_id BIGINT, company_id INTEGER REFERENCES companies(company_id) ON DELETE SET NULL,
 details TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS dividends (
 dividend_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 company_id INTEGER NOT NULL REFERENCES companies(company_id),
 amount_per_share NUMERIC(15,4) NOT NULL,
 tax_rate NUMERIC(6,2) NOT NULL DEFAULT 0,
 record_date DATE NOT NULL, payment_date DATE NOT NULL,
 status VARCHAR(30) NOT NULL DEFAULT 'declared',
 declared_by INTEGER REFERENCES users(user_id),
 first_approver_id INTEGER REFERENCES users(user_id), first_approved_at TIMESTAMP,
 final_approver_id INTEGER REFERENCES users(user_id), final_approved_at TIMESTAMP,
 paid_by INTEGER REFERENCES users(user_id), paid_at TIMESTAMP,
 payment_reference VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS dividend_payouts (
 payout_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 dividend_id BIGINT NOT NULL REFERENCES dividends(dividend_id) ON DELETE CASCADE,
 investor_id INTEGER NOT NULL REFERENCES investors(investor_id),
 shares_held BIGINT NOT NULL,
 gross_amount NUMERIC(18,2) NOT NULL,
 tax_amount NUMERIC(18,2) NOT NULL,
 net_amount NUMERIC(18,2) NOT NULL,
 status VARCHAR(25) NOT NULL DEFAULT 'pending',
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE (dividend_id, investor_id)
);
CREATE INDEX IF NOT EXISTS idx_orders_buy_status ON buy_orders(status,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_sell_status ON sell_orders(status,created_at);
CREATE INDEX IF NOT EXISTS idx_prices_company_date ON share_prices(company_id,date_recorded);
CREATE INDEX IF NOT EXISTS idx_messages_users ON messages(sender,receiver,date);
CREATE INDEX IF NOT EXISTS idx_audit_date ON audit_log(created_at DESC);
